// ---- modules/DomFacade.js
// A minimal DOM, built from a neutral tree, that is just big enough for the Anchor Modeler's
// Sisulator.objectify and MAP key functions. It is for hosts that have no DOM of their own: the
// generator that runs in Snowflake (tools/build-snowflake-generator.ps1) and the tests under Jint in the
// sisula repository. modules/XmlTree.js makes the tree from XML text. ES5, so it runs under Jint as well
// as in Node.
//
// Neutral tree: an element is { t: 1, n: name, a: [[name, value], ...], c: [children] }
// and a text node is { t: 3, v: text }. Any other node type is left out.
//
// Only the XPath that MAP.key.tie uses, '*[@attribute]', is supported; anything else throws.

var XPathResult = { ORDERED_NODE_ITERATOR_TYPE: 5 };

function buildDom(tree) {
    function make(n, parent) {
        var node = { parentNode: parent, firstChild: null, nextSibling: null };
        if (n.t === 3) {
            node.nodeType = 3;
            node.nodeName = '#text';
            node.nodeValue = n.v;
            node.attributes = { length: 0, item: function () { return null; } };
            return node;
        }
        node.nodeType = 1;
        node.nodeName = n.n;
        node.nodeValue = null;
        var attrs = [];
        for (var i = 0; i < n.a.length; i++) {
            attrs.push({ nodeName: n.a[i][0], nodeValue: n.a[i][1] });
        }
        node.attributes = { length: attrs.length, item: function (j) { return attrs[j]; } };
        node.getAttribute = function (name) {
            for (var k = 0; k < attrs.length; k++) if (attrs[k].nodeName === name) return attrs[k].nodeValue;
            return null;
        };
        node.childNodes = [];
        var previous = null;
        for (var c = 0; c < n.c.length; c++) {
            var child = make(n.c[c], node);
            node.childNodes.push(child);
            if (previous) previous.nextSibling = child; else node.firstChild = child;
            previous = child;
        }
        return node;
    }

    var root = make(tree, null);
    return {
        documentElement: root,
        evaluate: function (expression, context) {
            var m = /^\*\[@(\w+)\]$/.exec(expression);
            if (!m) throw new Error('dom-facade: unsupported XPath: ' + expression);
            var hits = [];
            for (var i = 0; i < context.childNodes.length; i++) {
                var child = context.childNodes[i];
                if (child.nodeType === 1 && child.getAttribute(m[1]) !== null) hits.push(child);
            }
            var index = 0;
            return { iterateNext: function () { return index < hits.length ? hits[index++] : null; } };
        }
    };
}

// ---- modules/Map.js
var MAP = {
    description: 'models from Anchor Modeling, http://www.anchormodeling.com',
    // name of the root element and resulting JSON object
    root: 'schema',
    // define 'keys' for elements that may occur more than once
    // on the same level in the XML document
    key: {
        knot: function(xml, fragment) {
            return fragment.getAttribute('mnemonic');
        },
        anchor: function(xml, fragment) {
            return fragment.getAttribute('mnemonic');
        },
        nexus: function(xml, fragment) {
            return fragment.getAttribute('mnemonic');
        },
        attribute: function(xml, fragment) {
            return fragment.getAttribute('mnemonic');
        },
        tie: function(xml, fragment) {
            var roles = xml.evaluate(
                    '*[@role]',
                    fragment,
                    null,
                    XPathResult.ORDERED_NODE_ITERATOR_TYPE, // document order
                    null
            );
            var key = '', role = roles.iterateNext();
            while(role) {
                key += role.getAttribute('type') + '_' + role.getAttribute('role');
                role = roles.iterateNext();
                if(role) key += '_';
            }
            return key;
        },
        anchorRole: function(xml, fragment) {
            return fragment.getAttribute('type') + '_' + fragment.getAttribute('role');
        },
        knotRole: function(xml, fragment) {
            return fragment.getAttribute('type') + '_' + fragment.getAttribute('role');
        },
        // Unified role element (new serialization). Backward compatible with legacy anchorRole/knotRole.
        role: function(xml, fragment) {
            // Uses same composite key logic (type + role name)
            return fragment.getAttribute('type') + '_' + fragment.getAttribute('role');
        },
        // WIP: keys sisula
        key: function(xml, fragment) {
            return fragment.getAttribute('of') + 
                   '|' +
                   fragment.getAttribute('route') + 
                   '|' +
                   fragment.getAttribute('stop');
        }
    },                
    // used to replace certain element names with others
    replacer: function(name) {
        switch(name) {
            case 'anchorRoles':
                return 'roles';
            case 'knotRoles':
                return 'roles';
            case 'nexuss': // objectifier naive plural of nexus
                return 'nexuses';
            default:
                return name;
        }
    }
};

// ---- Sisulator.objectify, from modules/Sisulator.js
var Sisulator = {
    objectify: function(xml, map) {
        var listSuffix = 's';
        function objectifier(xmlFragment, map, object) {
            // element node
            if(xmlFragment.nodeType === 1) {
                // if there are children or attributes we need a container
                if(xmlFragment.attributes.length > 0 || xmlFragment.firstChild) {
                    if(!object[xmlFragment.nodeName])
                        object[xmlFragment.nodeName] = new Object();
                    var partialObject = object[xmlFragment.nodeName];
                    if(typeof map.key[xmlFragment.nodeName] === 'function') {
                        var key = map.key[xmlFragment.nodeName](xml, xmlFragment);
                        if(key) {
                            partialObject = partialObject[key] = new Object();
                            partialObject.id = key;
                            var name = xmlFragment.nodeName + listSuffix;
                            name = map.replacer ? map.replacer(name) : name;
                            // reference the object from the array
                            if(!object[name])
                                object[name] = [];
                            object[name].push(key);
                        }
                    }
                    // process attributes
                    if (xmlFragment.attributes.length > 0) {
                        for (var j = 0; j < xmlFragment.attributes.length; j++) {
                            var attribute = xmlFragment.attributes.item(j);
                            partialObject[attribute.nodeName] = attribute.nodeValue;
                        }
                    }
                    // process children
                    var child = xmlFragment.firstChild;
                    if(child) objectifier(child, map, partialObject);
                }
            }
            // text node
            else if(xmlFragment.nodeType === 3) {
                // add content with underscore naming
                if(xmlFragment.nodeValue)
                    object['_' + xmlFragment.parentNode.nodeName] = xmlFragment.nodeValue;
            }
            // process siblings
            var sibling = xmlFragment.nextSibling;
            if(sibling) objectifier(sibling, map, object);
            return object;
        }
        // just initialize and return the result
        return objectifier(xml.documentElement, map, {});
    }
};

// ---- modules/Resolver.js
// Resolver: turns the modeler's `schema` object into the plain JSON that Sisula templates render.
//
// It does not reimplement any model logic. The `schema` object is the one the modeler builds
// (Sisulator.objectify, then Helpers.js and the naming conventions run on it) and this module
// flattens it into plain acyclic data:
//
//   - keyed maps plus their id lists (knot/knots, anchor/anchors, role/roles, ...) become one
//     array of objects, so that a template can `foreach` over them;
//   - isX()/hasX() predicates are called once and stored as booleans under the same name;
//   - iterator plumbing and other functions are dropped;
//   - back-references (parent, knot, anchor, nexus, entity) become shallow summaries, which is
//     what breaks the cycles. A summary holds the scalar fields, the predicates and the
//     metadata/description of the referenced object, not its collections.
//
// `schema.attributes` is the modeler's global attribute list (`allAttributes`), in its order.
//
// ES5 and no DOM: this file also runs outside the browser (Jint, for one), and must keep doing so.
// Anything that needs the page, such as fetching the scripts to run, lives in the caller.
var Resolver = (function () {
    // Properties that point back at another entity. They are serialised as summaries.
    var REFERENCES = { parent: 1, knot: 1, anchor: 1, nexus: 1, entity: 1 };
    // Inside an entity's `keys` (route -> stops), these point at entities too.
    var KEY_REFERENCES = { attribute: 1, tie: 1, role: 1, anchor: 1 };

    function isArray(v) { return Object.prototype.toString.call(v) === '[object Array]'; }
    function isObject(v) { return v !== null && typeof v === 'object' && !isArray(v); }
    function isBlank(s) { return typeof s === 'string' && !/\S/.test(s); }
    function isPredicate(name) { return /^(is|has)[A-Z]/.test(name) && !/^(isFirst|hasMore)/.test(name); }

    function allIn(ids, map) {
        for (var i = 0; i < ids.length; i++) {
            if (typeof ids[i] !== 'string' || !Object.prototype.hasOwnProperty.call(map, ids[i])) return false;
        }
        return true;
    }

    // Finds the keyed map that an array of ids points into. The map named after the array without
    // its plural 's' wins (roles/role, knotRoles/knotRole); otherwise any sibling map holding all ids.
    function findMap(obj, name, ids) {
        var single = name === 'nexuses' ? 'nexus' : name.replace(/s$/, '');
        if (single !== name && isObject(obj[single]) && allIn(ids, obj[single])) return { key: single, map: obj[single], paired: true };
        for (var k in obj) {
            if (Object.prototype.hasOwnProperty.call(obj, k) && k !== name && isObject(obj[k]) && allIn(ids, obj[k])) {
                return { key: k, map: obj[k], paired: false };
            }
        }
        return null;
    }

    function serialize(schema) {
        function serializeValue(v, inKeys) {
            if (isArray(v)) {
                var items = [];
                for (var i = 0; i < v.length; i++) items.push(serializeValue(v[i], inKeys));
                return items;
            }
            if (isObject(v)) return serializeObject(v, false, inKeys);
            return v;
        }

        function serializeObject(obj, summary, inKeys) {
            var out = {}, handled = {}, name, v;

            // Id lists become arrays of the objects they point at.
            if (!summary) {
                for (name in obj) {
                    if (!Object.prototype.hasOwnProperty.call(obj, name)) continue;
                    v = obj[name];
                    if (!isArray(v) || v.length === 0 || typeof v[0] !== 'string') continue;
                    var found = findMap(obj, name, v);
                    if (!found) continue;
                    var resolved = [];
                    for (var i = 0; i < v.length; i++) resolved.push(serializeValue(found.map[v[i]], inKeys));
                    out[name] = resolved;
                    handled[name] = true;
                    if (found.paired) handled[found.key] = true;
                }
            }

            for (name in obj) {
                if (!Object.prototype.hasOwnProperty.call(obj, name) || handled[name]) continue;
                v = obj[name];
                if (typeof v === 'function') {
                    if (isPredicate(name)) out[name] = !!v.call(obj);
                    else if (name === 'getEncryptionGroup') out.encryptionGroup = v.call(obj) || null;
                    continue;
                }
                if (v === undefined) continue;
                // Internals start with an underscore. Text content is stored the same way
                // (`_description`), but whitespace between elements is noise.
                if (name.charAt(0) === '_' && !(typeof v === 'string' && !isBlank(v))) continue;
                if (isObject(v) && (REFERENCES[name] || (inKeys && KEY_REFERENCES[name]))) {
                    out[name] = serializeObject(v, true, false);
                } else if (summary) {
                    if (!isObject(v) || name === 'metadata' || name === 'description') out[name] = serializeValue(v, false);
                } else {
                    out[name] = serializeValue(v, inKeys || name === 'keys');
                }
            }
            return out;
        }

        var result = serializeObject(schema, false, false);
        // The modeler's global attribute list, under a name that reads naturally in templates.
        result.attributes = serializeValue(schema.allAttributes, false);
