schema._iterator.knot = 0;
schema._iterator.anchor = 0;
schema._iterator.nexus = 0;
schema._iterator.attribute = 0;
schema._iterator.historizedAttribute = 0;
schema._iterator.tie = 0;
schema._iterator.historizedTie = 0;
