    }
}

// warn about naming clashes for business names
if(schema.BUSINESS_VIEWS) {
    var anchors = {};
    while (anchor = schema.nextAnchor()) {
        if(!anchors[anchor.businessName])
            anchors[anchor.businessName] = [anchor];
        else
            anchors[anchor.businessName].push(anchor);
        var attributes = {};
        while (attribute = anchor.nextAttribute()) {
            if(!attributes[attribute.businessName])
                attributes[attribute.businessName] = [attribute];
            else
                attributes[attribute.businessName].push(attribute);
        }
        for(businessName in attributes) {
            if(attributes[businessName].length > 1)
                alert(
                    "WARNING: The attributes " + attributes[businessName].join(' and ') +
                    " on the anchor " + anchor.name +
                    " all have the same business name: " + businessName + "."
                );
        }
    }
    for(businessName in anchors) {
        if(anchors[businessName].length > 1)
            alert(
                "WARNING: The anchors " + anchors[businessName].join(' and ') +
                " all have the same business name: " + businessName + "."
            );
    }
}


// second pass over anchor to set key names
while (anchor = schema.nextAnchor()) {
    if(anchor.keys) {
        var role, key, route, stop, component;
        for(route in anchor.keys) {
            key = anchor.keys[route];
            key.name = 'key' + D + anchor.mnemonic + D + anchor.descriptor + D + route;
            // Physical table name for materialized natural key attributes (drop 'key' prefix)
            key.tableName = anchor.mnemonic + D + anchor.descriptor + D + route;
            key.changingColumnName = anchor.mnemonic + D + schema.metadata.changingSuffix;
            for(stop in key.stops) {
                component = key.stops[stop];
                if(component.attribute) {
                    component.routedValueColumnName = (role ? role.role + D : '') + component.attribute.valueColumnName;
                    if(component.attribute.timeRange) {
                        component.routedChangingColumnName = (role ? role.role + D : '') + component.attribute.changingColumnName;
                    }
                    component.routedChangingColumnName = (role ? role.role + D : '') + component.attribute.valueColumnName + D + schema.metadata.changingSuffix;
                }
                role = component.role;
            }
        }
    }
} 

// second pass over nexus to set key names
var nexus;
while (nexus = schema.nextNexus()) {
var role;
    while (role = nexus.nextRole()) {
        role.name = role.type + D + role.role;
        if(role.knot) {
            role.businessName = role.role + D + (role.knot ? role.knot.descriptor : 'UnknownKnot');
            role.businessColumnName = role.businessName + D + businessIdentity;
        }
        else if(role.anchor) {
            role.businessName = role.anchor.descriptor + D + role.role;
            role.businessColumnName = role.businessName + D + businessIdentity;
        }
        else {
            // Fallback for roles that do not resolve to anchor or knot (e.g., nexus associations not yet modeled like ties)
            role.businessName = (role.role || 'role') + D + 'Unknown';
            role.businessColumnName = role.businessName + D + businessIdentity;
        }
        role.columnName = role.type + D + schema.metadata.identitySuffix + D + role.role;
        if(role.knot) {
            knot = role.knot;
            if(schema.IMPROVED) {
                role.knotValueColumnName = role.role + D + knot.valueColumnName;
                role.knotMetadataColumnName = role.role + D + knot.metadataColumnName;
                role.knotEquivalentColumnName = role.role + D + knot.equivalentColumnName;
                role.knotChecksumColumnName = role.role + D + knot.checksumColumnName;
            }
            else {
                role.knotValueColumnName = knot.valueColumnName;
                role.knotMetadataColumnName = knot.metadataColumnName;
                role.knotEquivalentColumnName = knot.equivalentColumnName;
                role.knotChecksumColumnName = knot.checksumColumnName;
            }
        }
    }
    if(nexus.keys) {
        var role, key, route, stop, component;
        for(route in nexus.keys) {
            key = nexus.keys[route];
            key.name = 'key' + D + nexus.mnemonic + D + nexus.descriptor + D + route;
            key.tableName = nexus.mnemonic + D + nexus.descriptor + D + route;
            key.changingColumnName = nexus.mnemonic + D + schema.metadata.changingSuffix;
            for(stop in key.stops) {
                component = key.stops[stop];
                if(component.attribute) {
                    component.routedValueColumnName = (role ? role.role + D : '') + component.attribute.valueColumnName;
                    if(component.attribute.timeRange) {
                        component.routedChangingColumnName = (role ? role.role + D : '') + component.attribute.changingColumnName;
                    }
                    component.routedChangingColumnName = (role ? role.role + D : '') + component.attribute.valueColumnName + D + schema.metadata.changingSuffix;
                }
                role = component.role; // may be undefined for pure attribute stops
            }
        }
    }
}

var tie;
while (tie = schema.nextTie()) {
    var name = '', bName = '';
    var role;
    while (role = tie.nextRole()) {
        role.name = role.type + D + role.role;
        if(role.knot) {
            role.businessName = role.role + D + (role.knot ? role.knot.descriptor : 'UnknownKnot');
            role.businessColumnName = role.businessName + D + businessIdentity;
        }
        else if(role.anchor) {
            role.businessName = role.anchor.descriptor + D + role.role;
            role.businessColumnName = role.businessName + D + businessIdentity;
        }
        else {
            // Fallback for roles that do not resolve to anchor or knot (e.g., nexus associations not yet modeled like ties)
            role.businessName = (role.role || 'role') + D + 'Unknown';
            role.businessColumnName = role.businessName + D + businessIdentity;
        }
        role.columnName = role.type + D + schema.metadata.identitySuffix + D + role.role;
        if(role.knot) {
            knot = role.knot;
            if(schema.IMPROVED) {
                role.knotValueColumnName = role.role + D + knot.valueColumnName;
                role.knotMetadataColumnName = role.role + D + knot.metadataColumnName;
                role.knotEquivalentColumnName = role.role + D + knot.equivalentColumnName;
                role.knotChecksumColumnName = role.role + D + knot.checksumColumnName;
            }
            else {
                role.knotValueColumnName = knot.valueColumnName;
                role.knotMetadataColumnName = knot.metadataColumnName;
                role.knotEquivalentColumnName = knot.equivalentColumnName;
                role.knotChecksumColumnName = knot.checksumColumnName;
            }
        }
        name += role.name;
        bName += role.businessName;
        if(tie.hasMoreRoles()) {
            name += D;
            bName += D;
        }
    }
    tie.name = name;
    tie.deletionName = tie.name + D + schema.metadata.deletionSuffix;
    tie.businessName = bName;
    tie.positName = tie.name + D + schema.metadata.positSuffix;
    tie.annexName = tie.name + D + schema.metadata.annexSuffix;
    tie.identityColumnName = tie.name + D + schema.metadata.identitySuffix;
    tie.positingColumnName = tie.name + D + schema.metadata.positingSuffix;
    tie.positorColumnName = tie.name + D + schema.metadata.positorSuffix;
    tie.reliabilityColumnName = tie.name + D + schema.metadata.reliabilitySuffix;
    tie.assertionColumnName = tie.name + D + schema.metadata.assertionSuffix;
    tie.capsule = tie.metadata.capsule || schema.metadata.encapsulation;
    tie.deletableColumnName = schema.metadata.deletablePrefix + D + tie.name;
    tie.deletionTimeColumnName = tie.name + D + schema.metadata.deletionSuffix;
    tie.metadataColumnName = schema.metadata.metadataPrefix + D + tie.name;
    tie.versionColumnName = tie.name + D + schema.metadata.versionSuffix;
    tie.statementTypeColumnName = tie.name + D + schema.metadata.statementTypeSuffix;
    if(tie.timeRange) {
        tie.changingColumnName = tie.name + D + schema.metadata.changingSuffix;
    }
    tie.toString = function() { return tie.name; };
}

// warn about naming clashes for business names
if(schema.BUSINESS_VIEWS) {
    var ties = {};
    while (tie = schema.nextTie()) {
        if(!ties[tie.businessName])
            ties[tie.businessName] = [tie];
        else
            ties[knot.businessName].push(tie);
    }
    for(businessName in ties) {
        if(ties[businessName].length > 1)
            alert(
                "WARNING: The ties " + ties[businessName].join(' and ') +
                " all have the same business name: " + businessName + "."
            );
    }
}
// ---- SQL/Snowflake/NamingConvention.js
// the following builds specific the naming convention of Anchor Modeling, change if you want something else

// set some hard coded defaults if they are missing
schema.metadata.encapsulation = schema.metadata.encapsulation || 'dbo';
schema.metadata.chronon = schema.metadata.chronon || 'datetime';

// knots get a dummy column too, when there are no metadata columns (anchors and nexuses get theirs in
// the common naming convention); the table definitions have a column there to end their list with
var knot;
while(knot = schema.nextKnot())
    knot.dummyColumnName = knot.mnemonic + D + schema.metadata.dummySuffix;

// nexuses take their identities from a sequence, like anchors and knots do (the common naming convention
// names the sequence of an anchor and a knot); a load can then draw an identity before the row is inserted
var nexus;
while(nexus = schema.nextNexus())
    nexus.identitySequenceName = nexus.name + D + schema.metadata.identitySuffix + D + 'SEQ';

// the identity of a posit (bi and crt) also comes from a sequence, named after the posit table; so every
// identity in a model that is generated has one, whether it is of a knot, anchor, nexus, attribute or tie
var posited, attribute;
while(posited = schema.nextAnchor())
    while(attribute = posited.nextAttribute())
        attribute.identitySequenceName = attribute.positName + D + schema.metadata.identitySuffix + D + 'SEQ';
while(posited = schema.nextNexus())
    while(attribute = posited.nextAttribute())
        attribute.identitySequenceName = attribute.positName + D + schema.metadata.identitySuffix + D + 'SEQ';
var tie;
while(tie = schema.nextTie())
    tie.identitySequenceName = tie.positName + D + schema.metadata.identitySuffix + D + 'SEQ';

// returns the description of a construct as an escaped string literal body, or null if it has none
var describe = function(construct) {
    if(!construct || !construct.description || !construct.description._description)
        return null;
    var text = String(construct.description._description).replace(/\s+/g, ' ').trim();
    if(text.length == 0)
        return null;
    return text.replace(/\\/g, '\\\\').replace(/'/g, "''");
};
// returns a COMMENT clause for a view column, since view column comments can only be given when the view is created
var columnCommentClause = function(construct) {
    var comment = describe(construct);
    return comment ? " COMMENT '" + comment + "'" : '';
};
// returns a COMMENT = clause for a view, placed before AS in the view definition
var viewCommentClause = function(construct) {
    var comment = describe(construct);
    return comment ? "COMMENT = '" + comment + "'" : '';
};
// ---- SQL/Snowflake/derive.js
// derive.js: the values the Snowflake templates need that Anchor's sisulets compute with helper
// functions or small expressions at generation time. The resolver runs it after Helpers.js and
// the naming conventions, in the same scope, so it can use their helpers and iterators.
//
// Only facts are derived here, never SQL. Where a sisulet calls columnCommentClause(x) or
// viewCommentClause(x), both thin wrappers over describe(x) in SQL/Snowflake/NamingConvention.js,
// the template reads x.comment and writes the COMMENT clause itself.
//
//   comment         the description as the body of a Snowflake string literal (describe(x)), or null
//   hasComment      whether there is one. Tested instead of `comment`, which a template would read
//                   as false for a description that is literally "0", "false" or "null".
//   attributeCount  the number of attributes of an anchor or nexus
//   roleCount       the number of roles of a nexus or tie
//   uniqueColumnName       the column that a knot is unique on: its checksum if it has one, else its value
//   comparedColumnName     the column that tells whether an attribute has changed: its checksum if it has one,
//                          else its value (a knotted attribute's value column is the reference to the knot)
//   isComparable           whether two values of the attribute can be compared with =; a geography, a geometry
//                          and the semi-structured types cannot, unless there is a checksum to compare
//
// The counts are data because a path in a template reaches only what the JSON holds. A template
// cannot ask an array for its length: JSON has no such member, and the JSON functions of SQL
// Server, which run the same templates, do not either.

function deriveComment(construct) {
    var comment = describe(construct);
    construct.comment = comment;
    construct.hasComment = comment !== null;
}

deriveComment(schema);

var knot;
while (knot = schema.nextKnot()) {
    deriveComment(knot);
    knot.uniqueColumnName = knot.hasChecksum() ? knot.checksumColumnName : knot.valueColumnName;
}

var anchor;
while (anchor = schema.nextAnchor()) {
    deriveComment(anchor);
    anchor.attributeCount = anchor.attributes ? anchor.attributes.length : 0;
}

var attribute;
while (attribute = schema.nextAttribute()) {
    deriveComment(attribute);
    var checksummed = !attribute.isKnotted() && attribute.hasChecksum();
    attribute.comparedColumnName = checksummed ? attribute.checksumColumnName : attribute.valueColumnName;
    attribute.isComparable = checksummed || attribute.isKnotted() || !/^\s*(geography|geometry|variant|object|array)\b/i.test(attribute.dataRange || '');
}

var nexus, role;
while (nexus = schema.nextNexus()) {
    deriveComment(nexus);
    nexus.attributeCount = nexus.attributes ? nexus.attributes.length : 0;
    nexus.roleCount = nexus.roles ? nexus.roles.length : 0;
    while (role = nexus.nextRole()) deriveComment(role);
}

var tie;
while (tie = schema.nextTie()) {
    deriveComment(tie);
    tie.roleCount = tie.roles ? tie.roles.length : 0;
    while (role = tie.nextRole()) deriveComment(role);
}
// Schema names. The templates write every other name inside double quotes, which keeps its case and lets it hold
// national characters; a schema is written as it is here. Snowflake accepts an unquoted name of letters (A-Z, a-z),
// digits, underscores and dollar signs, which it reads as upper case, so a schema like that stays as it is and
// matches the schema that someone created without quotes. Any other name has to be quoted, and then it is case
// sensitive, as the schema has to be created.
//
//   capsule         the schema of a knot, anchor, nexus, attribute or tie, quoted if it has to be
//   encapsulation   the schema in schema.metadata, the same
function quoteSchemaName(name) {
    if (name === undefined || name === null || /^[A-Za-z_][A-Za-z0-9_$]*$/.test(name)) return name;
    return '"' + String(name).replace(/"/g, '""') + '"';
}
schema.metadata.encapsulation = quoteSchemaName(schema.metadata.encapsulation);
var schemaOwner;
while (schemaOwner = schema.nextKnot()) schemaOwner.capsule = quoteSchemaName(schemaOwner.capsule);
while (schemaOwner = schema.nextAnchor()) schemaOwner.capsule = quoteSchemaName(schemaOwner.capsule);
while (schemaOwner = schema.nextNexus()) schemaOwner.capsule = quoteSchemaName(schemaOwner.capsule);
while (schemaOwner = schema.nextAttribute()) schemaOwner.capsule = quoteSchemaName(schemaOwner.capsule);
while (schemaOwner = schema.nextTie()) schemaOwner.capsule = quoteSchemaName(schemaOwner.capsule);
}

// ---- the function
var tree = XmlTree.parse(MODEL_XML);
var metadata = null;
for (var i = 0; i < tree.c.length; i++) if (tree.c[i].t === 1 && tree.c[i].n === 'metadata') metadata = tree.c[i];
if (!metadata) throw new Error('The model has no <metadata> element; it has to be an Anchor model as the modeler saves it (Generate > XML code).');
function setMetadata(name, value) {
    for (var k = 0; k < metadata.a.length; k++) if (metadata.a[k][0] === name) { metadata.a[k][1] = value; return; }
    metadata.a.push([name, value]);
}
setMetadata('databaseTarget', 'Snowflake');
if (TEMPORALIZATION !== null && TEMPORALIZATION !== undefined && TEMPORALIZATION !== '') {
    if (TEMPORALIZATION !== 'uni' && TEMPORALIZATION !== 'bi' && TEMPORALIZATION !== 'crt') throw new Error("The temporalization has to be 'uni', 'bi' or 'crt', not '" + TEMPORALIZATION + "'.");
    setMetadata('temporalization', TEMPORALIZATION);
}
var temporalization = 'uni';
for (var m = 0; m < metadata.a.length; m++) if (metadata.a[m][0] === 'temporalization') temporalization = metadata.a[m][1];
var schema = Sisulator.objectify(buildDom(tree), MAP)[MAP.root];
prepareSchema(schema, false, function () {}, { log: function () {}, error: function () {} });
return { bindingsVersion: 1, database: 'Snowflake', temporalization: temporalization, schema: Resolver.serialize(schema) };
$$;

