-- 4. The whole script for a model --------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION ANCHOR_GENERATE(MODEL_XML VARCHAR, WANTED VARCHAR)
RETURNS VARCHAR
AS
$$
SELECT
    LISTAGG(SISULATE(t.BODY, TO_JSON(r.bindings)), '') WITHIN GROUP (ORDER BY t.POSITION)
FROM
    ANCHOR_TEMPLATE t
CROSS JOIN (
    SELECT ANCHOR_BINDINGS(MODEL_XML, WANTED) AS bindings
) r
WHERE
    t.TEMPORALIZATION = r.bindings:temporalization::VARCHAR
$$;

-- 5. A check that the script has arrived as it was written -----------------------------------------------------------
-- It runs the generator on a model that is part of this script, and returns a sentence that says whether it works.
SELECT
    IFF(CONTAINS(g.script, 'CREATE TABLE') AND NOT CONTAINS(g.script, 'undefined'),
        'The Anchor generator is installed and works: ' || LENGTH(g.script) || ' characters of SQL for the example model',
        'The Anchor generator is installed, but its output is not what it should be: the script may have been changed on its way to Snowflake; install it again') AS RESULT
FROM (
    SELECT ANCHOR_GENERATE(
$$
<schema format="0.101.2">
<metadata changingRange="datetime" encapsulation="public" identity="int" metadataPrefix="Metadata" metadataType="int" metadataUsage="true" changingSuffix="ChangedAt" identitySuffix="ID" positIdentity="int" positGenerator="true" positingRange="datetime" positingSuffix="PositedAt" positorRange="tinyint" positorSuffix="Positor" reliabilityRange="decimal(5,2)" reliabilitySuffix="Reliability" defaultReliability="1" deleteReliability="0" assertionSuffix="Assertion" partitioning="false" entityIntegrity="true" restatability="true" idempotency="false" assertiveness="true" naming="improved" positSuffix="Posit" annexSuffix="Annex" chronon="timestamp_ntz(9)" now="sysdate()" dummySuffix="Dummy" versionSuffix="Version" statementTypeSuffix="StatementType" checksumSuffix="Checksum" businessViews="false" decisiveness="true" equivalence="false" equivalentSuffix="EQ" equivalentRange="tinyint" databaseTarget="Snowflake" temporalization="uni" deletability="false" deletablePrefix="Deletable" deletionSuffix="Deleted" privacy="Ignore" checksum="false" triggers="true" knotAliases="false" naturalKeyAttributes="false"/>
<knot mnemonic="GEN" descriptor="Gender" identity="tinyint" dataRange="varchar(42)">
<metadata capsule="public" generator="false"/>
</knot>
<anchor mnemonic="AC" descriptor="Actor" identity="int">
<metadata capsule="public" generator="true"/>
<attribute mnemonic="NAM" descriptor="Name" timeRange="datetime" dataRange="varchar(42)">
<metadata capsule="public"/>
</attribute>
<attribute mnemonic="GEN" descriptor="Gender" knotRange="GEN">
<metadata capsule="public"/>
</attribute>
</anchor>
<anchor mnemonic="PR" descriptor="Program" identity="int">
<metadata capsule="public" generator="true"/>
</anchor>
<tie>
<role role="part" type="AC" identifier="true"/>
<role role="in" type="PR" identifier="true"/>
<metadata capsule="public"/>
</tie>
</schema>
$$,
    'uni') AS script
) g;
